-- Disposable CI database only. Run bootstrap + 01 + seed + 04 + integration.sql + 06 first.
-- This test never connects to the user's Supabase project.
SELECT public.test_assert(public.dnm_v4_order_valid('{"production_no":"X","part_no":"P","customer":"C","qty":1,"received_qty":0,"unit_price":12.5,"order_amount":25,"grade_code":"Q","project":"시험"}'::jsonb)->>'grade_code'='Q','12 field validation retains grade');
SELECT public.test_assert(NOT has_function_privilege('authenticated','public.dnm_v41_sync_routing(uuid)','EXECUTE'),'route state helper not directly callable');
SELECT public.test_assert(NOT has_function_privilege('anon','public.dnm_v4_command(text,jsonb,uuid)','EXECUTE'),'anonymous v41 command denied');
SELECT public.test_assert((SELECT count(*)=4 FROM auth.users),'upgrade preserves accounts');
SELECT public.test_assert((SELECT name='이전 버전 보존 시험품' FROM public.dnm_portal_products WHERE code='LEGACY-V3'),'upgrade preserves legacy product');
DO $$
DECLARE a uuid:='11111111-1111-4111-8111-111111111111';w uuid:='33333333-3333-4333-8333-333333333333';viewer uuid:='44444444-4444-4444-8444-444444444444';
 eid uuid;wid uuid;tid uuid;oid uuid;rid uuid;opid uuid;checkid uuid;wlid uuid;k uuid;result jsonb;again jsonb;payload jsonb;st jsonb;rv integer;tv integer;ov integer;r public.dnm_v4_records;
BEGIN
 PERFORM set_config('request.jwt.claim.sub',a::text,true);
 PERFORM public.test_assert(public.dnm_v4_context()->>'version'='4.1.0','v41 context version');
 result:=public.dnm_v4_command('save_master','{"kind":"process_master","code":"PROC-V41","title":"시험선삭","data":{"active":true,"kind":"WORK","inspection_code":"M"}}',gen_random_uuid());
 result:=public.dnm_v4_command('save_master','{"kind":"material_master","code":"MAT-V41","title":"시험자재","data":{"active":true,"unit":"EA"}}',gen_random_uuid());
 PERFORM public.test_assert((SELECT count(*)=2 FROM public.dnm_v4_records WHERE code IN('PROC-V41','MAT-V41')),'new master types');
 result:=public.dnm_v4_command('save_master',jsonb_build_object('kind','equipment','code','EQ-V41','title','시험설비','data',jsonb_build_object('active',true,'manager_id',a)),gen_random_uuid());eid:=(result->>'id')::uuid;
 SELECT id INTO wid FROM public.dnm_v4_records WHERE kind='employee' AND code='EMP-TEST';
 PERFORM public.test_assert(wid IS NOT NULL,'reuse existing worker profile without duplicate employee');
 result:=public.dnm_v4_command('save_master',jsonb_build_object('kind','assignment','code','MAP-V41','title','시험매핑','data',jsonb_build_object('active',true,'equipment_id',eid,'employee_id',wid,'processes',jsonb_build_array('시험선삭'))),gen_random_uuid());
 st:=jsonb_build_array(jsonb_build_object('code','010','name','시험선삭','kind','WORK','equipment_id',eid,'employee_id',wid,'inspection_code','M','note','시험내용'),jsonb_build_object('code','020','name','확인검사','kind','INSPECTION','inspection_code','I'));
 result:=public.dnm_v4_command('save_master',jsonb_build_object('kind','route_template','code','PART-V41','title','시험제품','data',jsonb_build_object('steps',st,'active',true,'review_required',false)),gen_random_uuid());tid:=(result->>'id')::uuid;
 SELECT version INTO tv FROM public.dnm_v4_records WHERE id=tid;
 PERFORM public.test_assert((SELECT count(*)=1 FROM public.dnm_portal_products WHERE code='PART-V41'),'template creates missing product');
 payload:=jsonb_build_object('data',jsonb_build_object('production_no','ORDER-V41','customer','가상고객','po_no','PO-V41','part_no','PART-V41','part_name','시험제품','grade_code','Q','qty',10,'received_qty',2,'unit_price',1000,'order_amount',10000,'order_date','2026-10-01','due_date','2026-11-01','project','시험 Project','priority','NORMAL','source_status','신규'));
 result:=public.dnm_v4_command('save_order',payload,gen_random_uuid());oid:=(result->>'id')::uuid;
 SELECT * INTO r FROM public.dnm_v4_records WHERE id=oid;ov:=r.version;
 PERFORM public.test_assert(r.data->>'received_qty'='2' AND r.data->>'grade_code'='Q' AND r.data->>'order_amount'='10000','order12 fields persist');
 payload:=jsonb_build_object('order_id',oid,'order_version',ov,'template_id',tid,'template_version',tv,'manager_id',a,'lot','LOT-V41','issue_date','2026-10-28','steps',st,'work_type','양산','material_spec','시험재질','part_revision','A');
 PERFORM public.test_error(format('SELECT public.dnm_v4_command(%L,%L::jsonb,gen_random_uuid())','save_routing',jsonb_set(payload,'{template_version}',to_jsonb(tv+9))::text),'제품 Routing이 변경');
 k:=gen_random_uuid();result:=public.dnm_v4_command('save_routing',payload,k);rid:=(result->>'id')::uuid;again:=public.dnm_v4_command('save_routing',payload,k);PERFORM public.test_assert(result=again,'routing idempotent replay');
 SELECT id INTO opid FROM public.dnm_v4_records WHERE kind='operation' AND parent_id=rid AND data->>'seq'='1';
 SELECT id INTO checkid FROM public.dnm_v4_records WHERE kind='operation' AND parent_id=rid AND data->>'seq'='2';
 PERFORM public.test_assert((SELECT data->>'profile_id'=w::text AND data->>'equipment_code'='EQ-V41' FROM public.dnm_v4_records WHERE id=opid),'template assignment copied into order routing');
 SELECT * INTO r FROM public.dnm_v4_records WHERE id=rid;
 PERFORM public.dnm_v4_command('release_routing',jsonb_build_object('id',rid,'version',r.version),gen_random_uuid());
 PERFORM set_config('request.jwt.claim.sub',viewer::text,true);
 SELECT * INTO r FROM public.dnm_v4_records WHERE id=opid;
 PERFORM public.test_error(format('SELECT public.dnm_v4_command(%L,%L::jsonb,gen_random_uuid())','start_work',jsonb_build_object('id',opid,'version',r.version)::text),'권한');
 PERFORM set_config('request.jwt.claim.sub',w::text,true);
 result:=public.dnm_v4_command('start_work',jsonb_build_object('id',opid,'version',r.version,'input_mode','voice','voice_original','작업 시작'),gen_random_uuid());wlid:=(result->>'id')::uuid;
 UPDATE public.dnm_v4_records SET data=data||jsonb_build_object('start_at',now()-interval '1 hour') WHERE id=wlid;
 SELECT * INTO r FROM public.dnm_v4_records WHERE id=wlid;
 PERFORM public.test_error(format('SELECT public.dnm_v4_command(%L,%L::jsonb,gen_random_uuid())','finish_work',jsonb_build_object('id',wlid,'version',r.version,'total',4,'defect',0,'complete_operation',true)::text),'공정 완료는');
 PERFORM public.dnm_v4_command('finish_work',jsonb_build_object('id',wlid,'version',r.version,'total',4,'defect',0,'complete_operation',false,'input_mode','touch'),gen_random_uuid());
 PERFORM public.test_assert((SELECT state='WAIT' AND data->>'confirmed_qty'='4' FROM public.dnm_v4_records WHERE id=opid),'partial end leaves operation waiting');
 PERFORM public.test_assert((SELECT state='RELEASED' FROM public.dnm_v4_records WHERE id=rid),'partial end does not close route');
 SELECT * INTO r FROM public.dnm_v4_records WHERE id=opid;
 result:=public.dnm_v4_command('start_work',jsonb_build_object('id',opid,'version',r.version),gen_random_uuid());wlid:=(result->>'id')::uuid;
 UPDATE public.dnm_v4_records SET data=data||jsonb_build_object('start_at',now()-interval '5 minutes') WHERE id=wlid;
 SELECT * INTO r FROM public.dnm_v4_records WHERE id=wlid;
 PERFORM public.dnm_v4_command('finish_work',jsonb_build_object('id',wlid,'version',r.version,'pending',true),gen_random_uuid());
 PERFORM public.test_assert((SELECT state='PENDING' FROM public.dnm_v4_records WHERE id=opid),'unknown count blocks completion');
 SELECT * INTO r FROM public.dnm_v4_records WHERE id=wlid;
 PERFORM public.dnm_v4_command('confirm_work',jsonb_build_object('id',wlid,'version',r.version,'total',6,'defect',0,'complete_operation',true),gen_random_uuid());
 PERFORM public.test_assert((SELECT state='DONE' FROM public.dnm_v4_records WHERE id=opid),'verified total completes work operation');
 PERFORM public.test_assert((SELECT state='RELEASED' FROM public.dnm_v4_records WHERE id=rid),'inspection still pending keeps route active');
 PERFORM set_config('request.jwt.claim.sub',a::text,true);
 SELECT * INTO r FROM public.dnm_v4_records WHERE id=checkid;
 PERFORM public.dnm_v4_command('manager_step',jsonb_build_object('id',checkid,'version',r.version,'state','DONE','qty',10,'note','시험검사 완료'),gen_random_uuid());
 PERFORM public.test_assert((SELECT state='DONE' AND data->>'completed_at' IS NOT NULL FROM public.dnm_v4_records WHERE id=rid),'all operations done automatically ends routing');
 SELECT * INTO r FROM public.dnm_v4_records WHERE id=oid;
 PERFORM public.dnm_v4_command('quality',jsonb_build_object('id',oid,'version',r.version,'stage','FINAL','total',10,'defect',0,'report_no','TEST-FINAL'),gen_random_uuid());
 PERFORM public.test_assert((SELECT count(*)=1 FROM public.dnm_v4_records WHERE kind='quality' AND parent_id=oid),'final quality accepts ended routing');
END $$;
SELECT 'DNM v4.1 disposable integration tests completed' AS result;
